# Check CD8A expression
import numpy as np

leiden_key = 'leiden'

if 'CD8A' in adata.var_names:
    idx = np.where(adata.var_names == 'CD8A')[0][0]
    for cluster in ['0', '3', '12', '18']:
        mask = adata.obs[leiden_key] == cluster
        cluster_mean = adata[mask].X.toarray().mean(axis=0) if hasattr(adata[mask].X, 'toarray') else adata[mask].X.mean(axis=0)
        print("Cluster " + cluster + " CD8A: " + str(round(cluster_mean[idx], 4)))
else:
    print("CD8A not found")

